INSERT INTO `staff` (`id`, `nome`, `ruolo`, `categoria`, `bio`, `foto`, `ig`) VALUES
(1, 'Francesco Emiliani', 'Fondatore', 'founders', 'Presente fin dalle origini del Piazzetta Madness, porta avanti lo spirito del torneo con passione, visione e voglia di lasciare il segno sull’asfalto.', 'Emiliani_Francesco.jpg', ''),
(2, 'Nicolo\' Purifico', 'Fondatore', 'founders', 'Una delle firme storiche del Madness, contribuisce a mantenere vivo il carattere del torneo: competitivo, autentico e senza mezze misure.', 'Purifico_Nicolo\'.jpg', ''),
(3, 'Federico Pierleoni', 'Fondatore', 'founders', 'Parte della storia del Piazzetta Madness fin dal primo capitolo, rappresenta l’energia, la presenza e la mentalità che hanno dato forma al torneo.', 'Pierleoni_Federico.jpg', ''),
(4, 'Giorgio Monteriu\'', 'Fondatore', 'founders', 'Tra i volti originari del Madness, porta nel torneo continuità, appartenenza e quello spirito da playground che lo rende unico.', 'Monteriu\'_Giorgio.jpg', ''),
(5, 'Daniele Raccosta', 'Fondatore', 'founders', 'Presente fin dalla nascita del Piazzetta Madness, contribuisce a custodirne l’identità, la tradizione e la voglia di crescere anno dopo anno.', 'Daniele_Raccosta.jpg', ''),
(6, 'Alessia Principi', 'Social Media Manager & Graphic Designer', 'social', 'Dietro ogni grafica e post del Madness c’è lei: cura l’identità visiva del torneo e ne racconta ogni momento sui social.', 'Principi_Alessia.jpg', ''),
(7, 'Roberto Carbone', 'Fotografo Ufficiale', 'social', 'Cattura i momenti più belli del torneo, trasformando partite, emozioni e dettagli in immagini da ricordare.', 'Carbone_Roberto.jpg', ''),
(8, 'Nicolo\' Micucci', 'Graphic Designer', 'social', 'Cura l’identità visiva del Madness, dando forma grafica a contenuti, comunicazione e materiali del torneo.', 'Micucci_Nicolo\'.jpg', ''),
(9, 'Lorenzo Rebichini', 'Full Stack Developer', 'it', 'Sviluppa il tabellone digitale e gestisce il database del torneo. La tecnologia del Madness passa anche dalle sue mani.', 'Rebichini_Lorenzo.jpg', ''),
(10, 'Francesco Malaccari', 'Software Engineer', 'it', 'Progetta e integra il sistema backend del Madness, collegando server, dati e strumenti digitali al campo.', 'Malaccari_Francesco.jpg', ''),
(11, 'Mattia Boschi', 'Frontend Developer & UI/UX Designer', 'it', 'Cura interfaccia, grafica e integrazione del sito. La faccia digitale del Piazzetta Madness porta anche la sua firma.', 'Boschi_Mattia.jpg', ''),
(12, 'Paolo Tiberi', 'Scout & Statistiche', 'collaboratori', 'Raccoglie e interpreta i dati delle partite, trasformando ogni azione in statistiche utili per squadre, pubblico e torneo.', '', ''),
(13, 'Ermanno Senigagliesi', 'Tavolo Gara — Referto e Segnapunti', 'collaboratori', 'Gestisce referto e segnapunti con attenzione, contribuendo allo svolgimento preciso e ordinato delle partite.', '', ''),
(14, 'Emanuele Bevilacqua', 'Tavolo Gara — Referto e Segnapunti', 'collaboratori', 'Supporta il tavolo gara nella compilazione del referto e nell’aggiornamento del punteggio durante gli incontri.', '', ''),
(15, 'Francesco Senigagliesi', 'Tavolo Gara — Referto e Segnapunti', 'collaboratori', 'Collabora alla gestione del referto e del segnapunti, garantendo precisione e continuità nei momenti di gara.', '', ''),
(16, 'Matteo Caggiano', 'Tavolo Gara — Referto e Segnapunti', 'collaboratori', 'Fa parte del gruppo dedicato al tavolo gara, occupandosi del referto e del controllo del punteggio.', '', ''),
(17, 'Daniel Capaldo', 'Telecronista', 'collaboratori', 'Racconta le partite con voce, ritmo e passione, accompagnando il pubblico nei momenti più importanti del torneo.', '', ''),
(18, 'Nathan Zippo', 'Telecronista', 'collaboratori', 'Contribuisce alla telecronaca degli incontri, portando energia, coinvolgimento e ritmo al racconto delle gare.', 'Zippo_Nathan.jpg', ''),
(20, 'Veronica Carbone', 'Responsabile Stand & Accoglienza', 'collaboratori', 'Cura la gestione dello stand e dell’area accoglienza, mantenendo organizzazione, attenzione ai dettagli e continuità durante l’evento.', 'Carbone_Veronica.jpg', ''),
(21, 'Ilaria Pettorossi', 'Responsabile Stand & Accoglienza', 'collaboratori', 'Contribuisce alla gestione dello stand e dell’area accoglienza, supportando operatività, servizio e buon funzionamento durante le giornate del torneo.', 'Pettorossi._Ilaria.jpg', ''),
(22, 'Lorenzo Donati', 'DJ & Sound Manager', 'collaboratori', 'Cura musica e atmosfera dell’evento, accompagnando partite e pause con la giusta energia.', 'Donati_Lorenzo.jpg', ''),
(23, 'Annaluce Montevidoni', 'Brand ambassador', 'collaboratori', 'Il volto e lo stile dei video di presentazione del Madness: porta glamour e personalità davanti alla camera, trasformando ogni teaser in un piccolo show.', 'Montevidoni_Annaluce.jpg', '');
